// DXYN wrap y
{ const c=mk(); c.I=0x300; c.memory[0x300]=0x80; c.memory[0x301]=0x80; c.V[0]=0; c.V[1]=31; exec(c,0xD012);
  let top=0,bot=0;
  for(let y=0;y<32;y++){ if(c.display[y*64+0]) { if(y===31) bot++; else top++; } }
  console.log('DXYN wrap y=31: px at y=31 -> '+bot+', wrapped -> '+top); }

// 8XY7 final check
{ const c=mk(); c.V[0]=3; c.V[1]=9; exec(c,0x8017); console.log('SUBN V0=3,V1=9 -> V0='+c.V[0]+' VF='+c.V[0xF]); }

// FX33 final check
{ const c=mk(); c.I=0x400; c.V[0]=255; exec(c,0xF033); console.log('BCD 255 -> '+c.memory[0x400]+','+c.memory[0x401]+','+c.memory[0x402]); }
"}
